  "title": "Software Engineer Performance Review Rubric",
  "purpose": "Assess sustained performance against expectations for the engineer's current role and level.",
  "rating_scale": {
    "1": "Significantly below expectations: recurring gaps require substantial support.",
    "2": "Partially meets expectations: demonstrates some required behaviors, with inconsistent results.",
    "3": "Meets expectations: consistently delivers the outcomes expected at the current level.",
    "4": "Exceeds expectations: frequently delivers stronger outcomes or broader impact than expected.",
    "5": "Significantly exceeds expectations: demonstrates sustained, exceptional impact beyond current-level expectations."
  },
  "criteria": [
    {
      "name": "Delivery and execution",
      "weight_percent": 25,
      "evidence": [
        "Completed work and its outcomes",
        "Planning and progress updates",
        "Handling of dependencies and changing requirements"
      ],
      "anchors": {
        "1": "Frequently misses commitments without timely communication or effective recovery.",
        "3": "Delivers agreed work reliably, manages scope, and communicates risks early.",
        "5": "Consistently delivers high-impact outcomes through ambiguity and improves team execution."
      }
    },
    {
      "name": "Engineering quality",
      "weight_percent": 20,
      "evidence": [
        "Code and design reviews",
        "Appropriate testing and documentation",
        "Maintainability, reliability, and security outcomes"
      ],
      "anchors": {
        "1": "Repeatedly introduces avoidable defects or leaves important quality requirements unaddressed.",
        "3": "Produces maintainable code with appropriate tests, documentation, and operational safeguards.",
        "5": "Raises engineering standards and measurably reduces recurring defects or maintenance costs."
      }
    },
    {
      "name": "Technical judgment and problem solving",
      "weight_percent": 15,
      "evidence": [
        "Design decisions and tradeoffs",
        "Debugging investigations",
        "Appropriateness of solution complexity"
      ],
      "anchors": {
        "1": "Chooses approaches without adequately understanding requirements, constraints, or consequences.",
        "3": "Investigates systematically and selects practical solutions with clear tradeoffs.",
        "5": "Resolves unusually difficult problems and guides decisions that produce lasting technical value."
      }
    },
    {
      "name": "Ownership and impact",
      "weight_percent": 15,
      "evidence": [
        "Follow-through after release",
        "Response to defects and incidents where relevant",
        "Connection between engineering work and user or business needs"
      ],
      "anchors": {
        "1": "Requires repeated prompting to close gaps or address consequences of assigned work.",
        "3": "Owns work through completion, checks outcomes, and addresses issues within the role's scope.",
        "5": "Anticipates consequential gaps, coordinates solutions, and produces sustained improvements beyond assigned tasks."
      }
    },
    {
      "name": "Collaboration and communication",
      "weight_percent": 15,
      "evidence": [
        "Actionable peer and stakeholder feedback",
        "Code review interactions",
        "Knowledge sharing and cross-team coordination"
      ],
      "anchors": {
        "1": "Repeatedly leaves collaborators without necessary information or handles disagreement unconstructively.",
        "3": "Communicates clearly, gives useful feedback, shares context, and works respectfully through disagreements.",
        "5": "Improves collaboration across boundaries, resolves difficult disagreements, and consistently enables others to succeed."
      }
    },
    {
      "name": "Learning and improvement",
      "weight_percent": 10,
      "evidence": [
        "Application of feedback",
        "Progress on relevant development goals",
        "Improvements following mistakes or retrospectives"
      ],
      "anchors": {
        "1": "Repeatedly fails to apply relevant feedback or address known skill gaps.",
        "3": "Seeks feedback, develops relevant skills, and applies learning to improve results.",
        "5": "Turns learning into sustained improvements for both personal effectiveness and team capability."
      }
    }
  ],
  "scoring": {
    "method": "Rate each criterion from 1 to 5. Use ratings 2 and 4 when evidence falls between the adjacent anchors.",
    "formula": "Overall score = sum(rating × weight_percent) / sum(assessed weight_percent).",
    "insufficient_evidence": "Mark the criterion as not assessed, explain why, and exclude its weight from the calculation.",
    "interpretation": "Use the weighted score as an input to the overall judgment. Document significant strengths, gaps, and contextual factors."
  },
